head.b:skin:
/* ═══════════════════════════════════════════
   ytLiveQuiz — Mission Mode Theme
   Blogger Template · codecloudworld
   ═══════════════════════════════════════════ */

:root {
  --bg:     #070e07;
  --bg2:    #0d1a0d;
  --bg3:    #142814;
  --bg4:    #1a3a1a;
  --border: rgba(57,211,83,0.1);
  --border2:rgba(57,211,83,0.22);
  --border3:rgba(57,211,83,0.5);
  --text:   #d4f0d4;
  --text2:  #6fa86f;
  --text3:  #3a5a3a;
  --green:  #39d353;
  --amber:  #f0b429;
  --red:    #ff4040;
  --mono:   'IBM Plex Mono', monospace;
  --sans:   'DM Sans', sans-serif;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { height: 100%; scroll-behavior: smooth; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--mono);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  overflow-x: hidden;
  position: relative;
}

/* Scanlines */
body::after {
  content: '';
  pointer-events: none;
  position: fixed;
  inset: 0;
  background: repeating-linear-gradient(
    0deg, transparent, transparent 2px,
    rgba(0,0,0,0.07) 2px, rgba(0,0,0,0.07) 4px
  );
  z-index: 9999;
}

/* Grid bg */
body::before {
  content: '';
  pointer-events: none;
  position: fixed;
  inset: 0;
  background-image:
    linear-gradient(rgba(57,211,83,0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(57,211,83,0.025) 1px, transparent 1px);
  background-size: 40px 40px;
  z-index: 0;
}

/* ── BRAND BAR ── */
.qz-brand {
  width: 100%;
  max-width: 720px;
  padding: 1.75rem 2rem 0;
  display: flex;
  align-items: center;
  gap: 10px;
  position: relative;
  z-index: 1;
}
.qz-diamond {
  width: 8px; height: 8px;
  background: var(--green);
  transform: rotate(45deg);
  flex-shrink: 0;
  box-shadow: 0 0 8px var(--green);
}
.qz-brand-text {
  font-size: 13px;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--text2);
}
.qz-brand-text strong { color: var(--green); font-weight: 600; }
.qz-sys {
  margin-left: auto;
  font-size: 10px;
  letter-spacing: .1em;
  color: var(--text3);
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: 5px;
}
.qz-blip {
  width: 5px; height: 5px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 6px var(--green);
  display: inline-block;
  animation: blip 2s ease-in-out infinite;
}
@keyframes blip { 0%,100%{opacity:1} 50%{opacity:.2} }

/* ── MAIN CONTAINER ── */
.qz-wrap {
  width: 100%;
  max-width: 720px;
  padding: 2.5rem 2rem 4rem;
  display: flex;
  flex-direction: column;
  gap: 2rem;
  position: relative;
  z-index: 1;
  flex: 1;
}

/* ── MISSION CARD ── */
.mission-card {
  border: 1px solid var(--border2);
  border-radius: 4px;
  background: var(--bg2);
  position: relative;
  overflow: hidden;
}
.mission-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--green), var(--amber), transparent);
}
.mc-corner {
  position: absolute;
  width: 14px; height: 14px;
  border-color: var(--border3);
  border-style: solid;
}
.mc-tl { top: 8px;  left: 8px;  border-width: 1px 0 0 1px; }
.mc-tr { top: 8px;  right: 8px; border-width: 1px 1px 0 0; }
.mc-bl { bottom: 8px; left: 8px;  border-width: 0 0 1px 1px; }
.mc-br { bottom: 8px; right: 8px; border-width: 0 1px 1px 0; }
.mc-inner {
  padding: 2rem 2rem 2.25rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.mc-header {
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  gap: 10px;
  flex-wrap: wrap;
  width: 100%;
}
.mc-label {
  font-size: 10px;
  letter-spacing: .15em;
  text-transform: uppercase;
  color: var(--text3);
}
.mc-label span { color: var(--green); font-weight: 600; }

/* Status badges */
.qz-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  letter-spacing: .1em;
  text-transform: uppercase;
  padding: 3px 10px;
  border-radius: 2px;
}
.badge-standby {
  background: rgba(57,211,83,.07);
  border: 1px solid rgba(57,211,83,.2);
  color: var(--green);
}
.badge-live {
  background: rgba(255,64,64,.1);
  border: 1px solid rgba(255,64,64,.3);
  color: var(--red);
  display: none;
}
.badge-ended {
  background: rgba(58,90,58,.2);
  border: 1px solid var(--border);
  color: var(--text3);
  display: none;
}
.qz-pulse {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: currentColor;
  flex-shrink: 0;
  animation: pulse 1.2s ease-in-out infinite;
}
@keyframes pulse { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:.3;transform:scale(.75)} }

.exam-tag {
  display: inline-block;
  font-size: 10px;
  letter-spacing: .1em;
  text-transform: uppercase;
  padding: 3px 12px;
  border-radius: 2px;
  margin-bottom: 1rem;
  background: rgba(240,180,41,.08);
  border: 1px solid rgba(240,180,41,.22);
  color: var(--amber);
}

.mission-title {
  font-size: 22px;
  font-weight: 600;
  color: var(--text);
  line-height: 1.3;
  margin-bottom: 1.25rem;
  text-shadow: 0 0 20px rgba(57,211,83,.12);
}

.mc-meta {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: .75rem 2rem;
  margin-bottom: 1.75rem;
}
.mc-meta-item {
  font-size: 12px;
  color: var(--text2);
  letter-spacing: .04em;
  display: flex;
  align-items: center;
  gap: 6px;
}
.mc-meta-item::before { content: '◈'; color: var(--text3); font-size: 10px; }

/* Tactical countdown */
.tac-timer {
  background: none;
  border: none;
  padding: 0;
  margin-bottom: 2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .75rem;
  width: 100%;
}
.tac-label {
  font-size: 10px;
  letter-spacing: .15em;
  text-transform: uppercase;
  color: var(--text3);
}
.tac-units { display: flex; align-items: flex-end; gap: .625rem; }
.tac-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  background: var(--bg3);
  border: 1px solid var(--border2);
  border-radius: 4px;
  padding: 1.25rem 1.5rem 1rem;
  min-width: 72px;
  position: relative;
}
.tac-unit::after {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 2px;
  background: var(--green);
  border-radius: 0 0 4px 4px;
  opacity: .35;
}
.tac-val {
  font-size: 54px;
  font-weight: 600;
  color: var(--green);
  line-height: 1;
  min-width: 2ch;
  text-align: center;
  text-shadow: 0 0 20px rgba(57,211,83,.55);
  transition: color .3s;
  letter-spacing: -.02em;
}
.tac-val.warn {
  color: var(--amber);
  text-shadow: 0 0 20px rgba(240,180,41,.5);
}
.tac-val.warn ~ .tac-unit::after { background: var(--amber); }
.tac-val.danger {
  color: var(--red);
  text-shadow: 0 0 20px rgba(255,64,64,.5);
  animation: dpulse .6s ease-in-out infinite;
}
@keyframes dpulse { 0%,100%{opacity:1} 50%{opacity:.45} }
.tac-lbl {
  font-size: 9px;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--text3);
}
.tac-sep {
  font-size: 40px;
  color: var(--text3);
  opacity: .4;
  padding-bottom: 1.5rem;
  line-height: 1;
  flex-shrink: 0;
}

/* Buttons */
.btn-row { display: flex; gap: 14px; flex-wrap: wrap; justify-content: center; }
.qz-btn {
  font-family: var(--mono);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  padding: 14px 36px;
  border-radius: 2px;
  cursor: pointer;
  transition: all .15s;
  border: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  white-space: nowrap;
}
.btn-register {
  background: transparent;
  border: 1px solid var(--border2);
  color: var(--text2);
}
.btn-register:hover {
  border-color: var(--border3);
  color: var(--text);
  background: rgba(57,211,83,.05);
}
.btn-participate {
  background: rgba(57,211,83,.1);
  border: 1px solid var(--border2);
  color: var(--green);
  cursor: pointer;
}
.btn-participate:hover {
  background: rgba(57,211,83,.18);
  border-color: var(--border3);
  box-shadow: 0 0 16px rgba(57,211,83,.15);
}
.btn-participate.is-live {
  background: rgba(255,64,64,.12);
  border-color: var(--red);
  color: var(--red);
  opacity: 1;
  cursor: pointer;
  box-shadow: 0 0 16px rgba(255,64,64,.22);
  animation: liveGlow 1.5s ease-in-out infinite;
}
@keyframes liveGlow { 0%,100%{box-shadow:0 0 16px rgba(255,64,64,.22)} 50%{box-shadow:0 0 28px rgba(255,64,64,.4)} }
.btn-participate.is-live:hover { background: rgba(255,64,64,.2); }

/* ── DIVIDER ── */
.qz-divider {
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--border2), transparent);
  position: relative;
  z-index: 1;
}

/* ── MISSION LOG ── */
.mission-log { position: relative; z-index: 1; }
.log-header {
  font-size: 10px;
  letter-spacing: .15em;
  text-transform: uppercase;
  color: var(--text3);
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 8px;
}
.log-header::before { content: '//'; color: var(--green); opacity: .6; }
.log-list { display: flex; flex-direction: column; }
.log-item {
  display: grid;
  grid-template-columns: 42px 1fr 60px auto;
  align-items: center;
  gap: 1rem;
  padding: 13px 0;
  border-bottom: 1px solid var(--border);
  transition: background .15s;
}
.log-item:last-child { border-bottom: none; }
.log-item:hover { background: rgba(57,211,83,.03); }
.log-num { font-size: 11px; color: var(--text3); letter-spacing: .05em; }
.log-topic { font-size: 13px; color: var(--text); font-weight: 500; }
.log-topic small { display: block; font-size: 11px; color: var(--text2); margin-top: 1px; font-weight: 400; }
.log-date { font-size: 11px; color: var(--text2); white-space: nowrap; }
.log-badge {
  font-size: 10px; padding: 2px 8px; border-radius: 2px;
  letter-spacing: .06em; text-transform: uppercase; white-space: nowrap;
}
.b-open { background: rgba(57,211,83,.09); color: var(--green); border: 1px solid rgba(57,211,83,.2); }
.b-soon { background: rgba(240,180,41,.09); color: var(--amber); border: 1px solid rgba(240,180,41,.2); }
.b-tba  { background: var(--bg3); color: var(--text3); border: 1px solid var(--border); }

/* ── SINGLE POST / QUIZ RECAP ── */
.qz-post-full {
  border: 1px solid var(--border2);
  border-radius: 4px;
  background: var(--bg2);
  position: relative;
  overflow: hidden;
}
.qz-post-full::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--green), var(--amber), transparent);
}
.qz-post-inner { padding: 2rem 2rem 2.5rem; }
.qz-post-badge {
  font-size: 10px; letter-spacing: .15em; text-transform: uppercase;
  color: var(--text3); margin-bottom: .75rem;
}
.qz-post-title {
  font-size: 26px; font-weight: 600; color: var(--text);
  line-height: 1.25; margin-bottom: 1rem;
  font-family: var(--mono);
}
.qz-post-meta {
  display: flex; flex-wrap: wrap; gap: .75rem 1.5rem;
  margin-bottom: 1.5rem;
  padding-bottom: 1.25rem;
  border-bottom: 1px solid var(--border);
}
.qz-post-meta span,
.qz-post-meta a {
  font-size: 12px; color: var(--text2);
  text-decoration: none; letter-spacing: .04em;
}
.qz-post-meta a { color: var(--green); }
.qz-post-meta a:hover { color: var(--text); }
.qz-post-body {
  font-family: var(--sans);
  font-size: 15px;
  color: var(--text2);
  line-height: 1.75;
}
.qz-post-body h1,
.qz-post-body h2,
.qz-post-body h3 {
  font-family: var(--mono);
  color: var(--text);
  margin: 1.75rem 0 .75rem;
  line-height: 1.25;
}
.qz-post-body h1 { font-size: 22px; }
.qz-post-body h2 { font-size: 19px; color: var(--green); }
.qz-post-body h3 { font-size: 16px; color: var(--amber); }
.qz-post-body p  { margin-bottom: 1rem; }
.qz-post-body a  { color: var(--green); text-decoration: none; }
.qz-post-body a:hover { color: var(--text); }
.qz-post-body strong { color: var(--text); font-weight: 600; }
.qz-post-body ul, .qz-post-body ol {
  margin: .75rem 0 1rem 1.25rem;
}
.qz-post-body li { margin-bottom: .4rem; }
.qz-post-body blockquote {
  border-left: 3px solid var(--green);
  background: var(--bg3);
  padding: .875rem 1.25rem;
  margin: 1rem 0;
  border-radius: 0 3px 3px 0;
  color: var(--text);
}
.qz-post-body code {
  font-family: var(--mono);
  font-size: 12.5px;
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: 3px;
  padding: 1px 6px;
  color: var(--green);
}
.qz-post-body pre {
  background: #040904;
  border: 1px solid var(--border2);
  border-radius: 4px;
  padding: 1.25rem;
  overflow-x: auto;
  font-family: var(--mono);
  font-size: 13px;
  line-height: 1.7;
  color: var(--text);
  margin: 1rem 0;
}
.qz-post-body pre code { background: none; border: none; padding: 0; }
.qz-post-body img { max-width: 100%; border-radius: 4px; border: 1px solid var(--border2); }
.qz-post-body table {
  width: 100%; border-collapse: collapse;
  margin: 1rem 0; font-size: 14px;
}
.qz-post-body th {
  background: var(--bg3); color: var(--green);
  font-family: var(--mono); font-size: 11px;
  text-transform: uppercase; letter-spacing: .08em;
  padding: 10px 14px; text-align: left;
  border-bottom: 1px solid var(--border2);
}
.qz-post-body td {
  padding: 10px 14px; border-bottom: 1px solid var(--border);
  color: var(--text2);
}
.qz-post-labels {
  display: flex; flex-wrap: wrap; gap: 6px;
  margin-top: 1.75rem; padding-top: 1.25rem;
  border-top: 1px solid var(--border);
}
.qz-post-labels a {
  font-family: var(--mono); font-size: 11px;
  padding: 3px 10px; border-radius: 2px;
  background: rgba(57,211,83,.08);
  border: 1px solid rgba(57,211,83,.2);
  color: var(--green); text-decoration: none;
  letter-spacing: .06em; text-transform: uppercase;
  transition: all .15s;
}
.qz-post-labels a:hover { background: rgba(57,211,83,.15); color: var(--text); }

/* ── PAGINATION ── */
.qz-pager {
  display: flex; justify-content: space-between;
  padding-top: 1rem;
}
.qz-pager a {
  font-family: var(--mono); font-size: 12px;
  letter-spacing: .06em; text-transform: uppercase;
  color: var(--text2); text-decoration: none;
  padding: 8px 16px; border-radius: 2px;
  border: 1px solid var(--border);
  transition: all .15s;
}
.qz-pager a:hover { border-color: var(--border2); color: var(--green); }

/* ── FOOTER ── */
.qz-footer {
  width: 100%;
  border-top: 1px solid var(--border);
  text-align: center;
  padding: 1.5rem 2rem;
  position: relative; z-index: 1;
}
.qz-footer p { font-size: 11px; color: var(--text3); letter-spacing: .06em; }
.qz-footer a { color: var(--text2); text-decoration: none; }
.qz-footer a:hover { color: var(--green); }

/* ── 404 ── */
.qz-404 {
  text-align: center; padding: 4rem 2rem;
  position: relative; z-index: 1;
}
.qz-404 .code-404 {
  font-size: 72px; font-weight: 600; color: var(--text3);
  line-height: 1; text-shadow: 0 0 30px rgba(57,211,83,.2);
}
.qz-404 p { font-size: 14px; color: var(--text2); margin: 1rem 0 1.5rem; }
.qz-404 a {
  font-size: 12px; letter-spacing: .1em; text-transform: uppercase;
  color: var(--green); border: 1px solid var(--border2);
  padding: 10px 24px; border-radius: 2px; text-decoration: none;
  transition: all .15s;
}
.qz-404 a:hover { background: rgba(57,211,83,.07); border-color: var(--border3); }

/* ── RESPONSIVE ── */
@media (max-width: 600px) {
  .tac-unit { min-width: 58px; padding: 1rem 1rem .875rem; }
  .tac-val  { font-size: 40px; }
  .tac-sep  { font-size: 30px; padding-bottom: 1.25rem; }
}
@media (max-width: 520px) {
  .qz-wrap { padding: 2rem 1.25rem 3.5rem; }
  .mc-inner { padding: 1.25rem 1rem 1.75rem; }
  .mission-title { font-size: 19px; }
  .tac-unit { min-width: 50px; padding: .875rem .75rem .75rem; }
  .tac-val  { font-size: 34px; }
  .tac-sep  { font-size: 26px; padding-bottom: 1.1rem; }
  .btn-row  { flex-direction: column; }
  .btn-row .qz-btn { width: 100%; justify-content: center; }
  .log-date { display: none; }
  .log-item { grid-template-columns: 36px 1fr auto; }
  .qz-post-inner { padding: 1.25rem; }
  .qz-post-title { font-size: 20px; }
}

/* ── REGISTRATION FORM ── */
.rp-card {
  background: var(--bg2);
  border: 1px solid var(--border2);
  border-radius: 6px;
  position: relative;
  overflow: hidden;
}
.rp-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--green), var(--amber), transparent);
}
.rp-c { position: absolute; width: 14px; height: 14px; border-color: var(--border3); border-style: solid; }
.rp-tl { top: 8px;    left: 8px;  border-width: 1px 0 0 1px; }
.rp-tr { top: 8px;    right: 8px; border-width: 1px 1px 0 0; }
.rp-bl { bottom: 8px; left: 8px;  border-width: 0 0 1px 1px; }
.rp-br { bottom: 8px; right: 8px; border-width: 0 1px 1px 0; }
.rp-head { padding: 1.75rem 1.75rem 1.5rem; border-bottom: 1px solid var(--border); }
.rp-badge {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 10px; letter-spacing: .15em; text-transform: uppercase;
  padding: 3px 10px; border-radius: 2px;
  background: rgba(57,211,83,.07); border: 1px solid rgba(57,211,83,.2);
  color: var(--green); margin-bottom: 1rem;
}
.rp-badge-dot {
  width: 5px; height: 5px; border-radius: 50%;
  background: var(--green); box-shadow: 0 0 6px var(--green);
  display: inline-block; animation: rp-blink 2s ease-in-out infinite;
}
@keyframes rp-blink { 0%,100%{opacity:1} 50%{opacity:.2} }
.rp-title { font-size: 20px; font-weight: 600; color: var(--text); line-height: 1.3; margin-bottom: .375rem; }
.rp-meta { display: flex; flex-wrap: wrap; gap: .35rem 1.25rem; font-size: 11px; color: var(--text2); margin-top: .625rem; }
.rp-meta span::before { content: '◈  '; color: var(--text3); }
.rp-body { padding: 1.75rem; }
.rp-row { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; margin-bottom: 1.125rem; }
.rp-row.full { grid-template-columns: 1fr; }
.rp-field { display: flex; flex-direction: column; gap: 5px; }
.rp-label { font-size: 10px; letter-spacing: .12em; text-transform: uppercase; color: var(--text3); display: flex; align-items: center; gap: 5px; }
.rp-req { color: var(--amber); font-size: 13px; line-height: 1; }
.rp-input, .rp-select {
  background: var(--bg3); border: 1px solid var(--border2); border-radius: 3px;
  color: var(--text); font-family: var(--mono); font-size: 13px;
  padding: 10px 13px; outline: none; width: 100%; box-sizing: border-box;
  transition: border-color .15s, box-shadow .15s;
}
.rp-select { cursor: pointer; appearance: none; -webkit-appearance: none; }
.rp-select option { background: var(--bg3); color: var(--text); }
.rp-input::placeholder { color: var(--text3); }
.rp-input:focus, .rp-select:focus { border-color: var(--border3); box-shadow: 0 0 0 3px rgba(57,211,83,.09); }
.rp-input.err, .rp-select.err, .rp-phone.err { border-color: rgba(255,64,64,.5); }
.rp-sel-wrap { position: relative; }
.rp-sel-arrow { position: absolute; right: 11px; top: 50%; transform: translateY(-50%); pointer-events: none; color: var(--text3); font-size: 10px; }
.rp-err  { font-size: 10px; color: var(--red); display: none; }
.rp-err.show { display: block; }
.rp-phone { display: flex; border: 1px solid var(--border2); border-radius: 3px; overflow: hidden; transition: border-color .15s, box-shadow .15s; }
.rp-phone:focus-within { border-color: var(--border3); box-shadow: 0 0 0 3px rgba(57,211,83,.09); }
.rp-pfx { background: var(--bg4); border-right: 1px solid var(--border2); color: var(--text2); font-family: var(--mono); font-size: 13px; padding: 10px 12px; display: flex; align-items: center; gap: 5px; flex-shrink: 0; white-space: nowrap; }
.rp-pnum { background: var(--bg3); border: none; color: var(--text); font-family: var(--mono); font-size: 13px; padding: 10px 13px; outline: none; width: 100%; }
.rp-pnum::placeholder { color: var(--text3); }
.rp-dob { display: grid; grid-template-columns: 1fr 1fr 1.3fr; gap: .5rem; }
.rp-div { height: 1px; margin: 1.375rem 0; background: linear-gradient(90deg, transparent, var(--border2), transparent); }
.rp-rlbl { font-size: 10px; letter-spacing: .12em; text-transform: uppercase; color: var(--text3); margin-bottom: .625rem; display: flex; align-items: center; gap: 5px; }
.rp-ropts { display: flex; flex-direction: column; gap: .4rem; }
.rp-ropt { display: flex; align-items: center; gap: 11px; cursor: pointer; padding: 9px 13px; border-radius: 3px; border: 1px solid var(--border); background: var(--bg3); transition: border-color .15s, background .15s; }
.rp-ropt:hover { border-color: var(--border2); background: var(--bg4); }
.rp-ropt.yes { border-color: rgba(57,211,83,.35); background: rgba(57,211,83,.04); }
.rp-ropt.no  { border-color: rgba(255,64,64,.30); background: rgba(255,64,64,.03); }
.rp-ropt input[type='radio'] { appearance: none; -webkit-appearance: none; width: 15px; height: 15px; border: 1px solid var(--border2); border-radius: 50%; background: var(--bg); flex-shrink: 0; cursor: pointer; position: relative; transition: border-color .15s; }
.rp-ropt input[type='radio']:checked { border-color: var(--green); }
.rp-ropt input[type='radio']:checked::after { content: ''; position: absolute; top: 50%; left: 50%; transform: translate(-50%,-50%); width: 6px; height: 6px; border-radius: 50%; background: var(--green); box-shadow: 0 0 5px rgba(57,211,83,.6); }
.rp-ropt-txt { font-size: 13px; color: var(--text); font-weight: 500; flex: 1; line-height: 1.3; }
.rp-ropt-txt small { display: block; font-size: 11px; color: var(--text2); font-weight: 400; margin-top: 2px; }
.rp-ropt-ico { font-size: 16px; flex-shrink: 0; }
.rp-sub { display: none; margin-top: .875rem; padding: 1rem 1.125rem; border: 1px solid rgba(255,64,64,.22); border-radius: 3px; background: rgba(255,64,64,.04); }
.rp-sub.show { display: block; }
.rp-sub-txt { font-size: 12px; color: var(--text2); margin-bottom: .875rem; line-height: 1.6; }
.rp-sub-txt strong { color: var(--amber); }
.rp-yt-btn { display: inline-flex; align-items: center; gap: 8px; background: #ff0000; color: #fff; font-family: var(--mono); font-size: 12px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; padding: 9px 16px; border-radius: 3px; text-decoration: none; transition: background .15s, box-shadow .15s; }
.rp-yt-btn:hover { background: #cc0000; color: #fff; box-shadow: 0 0 14px rgba(255,0,0,.3); }
.rp-actions { margin-top: 1.5rem; display: flex; flex-direction: column; align-items: center; gap: .5rem; }
.rp-note { font-size: 10px; color: var(--text3); text-align: center; letter-spacing: .04em; }
.rp-submit { width: 100%; display: flex; align-items: center; justify-content: center; gap: 10px; background: rgba(57,211,83,.12); border: 1px solid var(--border2); border-radius: 3px; color: var(--green); font-family: var(--mono); font-size: 14px; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; padding: 13px 36px; cursor: pointer; transition: all .15s; }
.rp-submit:hover { background: rgba(57,211,83,.2); border-color: var(--border3); box-shadow: 0 0 18px rgba(57,211,83,.15); }
.rp-submit:disabled { opacity: .5; cursor: not-allowed; pointer-events: none; }
.rp-spin { width: 14px; height: 14px; border: 2px solid rgba(57,211,83,.3); border-top-color: var(--green); border-radius: 50%; animation: rp-spin .7s linear infinite; display: none; flex-shrink: 0; }
.rp-submit.loading .rp-spin { display: block; }
.rp-submit.loading .rp-stxt { display: none; }
@keyframes rp-spin { to { transform: rotate(360deg); } }
.rp-ok { display: none; text-align: center; padding: 3rem 1.75rem; }
.rp-ok.show { display: block; }
.rp-ok-ico { width: 62px; height: 62px; margin: 0 auto 1.25rem; border: 2px solid var(--green); border-radius: 50%; display: flex; align-items: center; justify-content: center; box-shadow: 0 0 20px rgba(57,211,83,.22); animation: rp-pop .45s cubic-bezier(.34,1.56,.64,1) forwards; }
@keyframes rp-pop { from{transform:scale(0);opacity:0} to{transform:scale(1);opacity:1} }
.rp-ok-ico svg { color: var(--green); }
.rp-ok-title { font-size: 19px; font-weight: 600; color: var(--green); margin-bottom: .625rem; text-shadow: 0 0 18px rgba(57,211,83,.3); }
.rp-ok-msg   { font-size: 13px; color: var(--text2); line-height: 1.65; margin-bottom: .75rem; }
.rp-ok-meta  { font-size: 11px; color: var(--text3); letter-spacing: .06em; margin-bottom: 1.75rem; }
.rp-back { display: inline-flex; align-items: center; gap: 7px; font-size: 12px; letter-spacing: .1em; text-transform: uppercase; color: var(--text2); border: 1px solid var(--border); padding: 9px 22px; border-radius: 3px; text-decoration: none; transition: all .15s; }
.rp-back:hover { border-color: var(--border2); color: var(--green); }
@media (max-width: 520px) {
  .rp-row { grid-template-columns: 1fr; }
  .rp-body,.rp-head { padding: 1.25rem; }
  .rp-dob  { grid-template-columns: 1fr 1fr 1fr; }
}

/* ── Participate form ── */
.pp-card { background: var(--bg2); border: 1px solid var(--border2); border-radius: 6px; position: relative; overflow: hidden; }
.pp-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 2px; background: linear-gradient(90deg, transparent, #f0b429, var(--green), transparent); }
.pp-c { position: absolute; width: 14px; height: 14px; border-color: rgba(57,211,83,0.50); border-style: solid; }
.pp-tl { top: 8px;    left: 8px;  border-width: 1px 0 0 1px; }
.pp-tr { top: 8px;    right: 8px; border-width: 1px 1px 0 0; }
.pp-bl { bottom: 8px; left: 8px;  border-width: 0 0 1px 1px; }
.pp-br { bottom: 8px; right: 8px; border-width: 0 1px 1px 0; }
.pp-head { padding: 1.75rem 1.75rem 1.5rem; border-bottom: 1px solid rgba(57,211,83,0.10); }
.pp-badge { display: inline-flex; align-items: center; gap: 6px; font-size: 10px; letter-spacing: .15em; text-transform: uppercase; padding: 3px 10px; border-radius: 2px; background: rgba(240,180,41,.07); border: 1px solid rgba(240,180,41,.25); color: #f0b429; margin-bottom: 1rem; }
.pp-badge-dot { width: 5px; height: 5px; border-radius: 50%; background: #f0b429; box-shadow: 0 0 6px #f0b429; display: inline-block; animation: pp-blink 2s ease-in-out infinite; }
@keyframes pp-blink { 0%,100%{opacity:1} 50%{opacity:.2} }
.pp-title { font-size: 20px; font-weight: 600; color: var(--text); line-height: 1.3; margin-bottom: .375rem; }
.pp-meta { display: flex; flex-wrap: wrap; gap: .35rem 1.25rem; font-size: 11px; color: var(--text2); margin-top: .625rem; }
.pp-meta span::before { content: '◈  '; color: var(--text3); }
.pp-body { padding: 1.75rem; }
.pp-row { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; margin-bottom: 1.125rem; }
.pp-row.full { grid-template-columns: 1fr; }
.pp-field { display: flex; flex-direction: column; gap: 5px; }
.pp-label { font-size: 10px; letter-spacing: .12em; text-transform: uppercase; color: var(--text3); display: flex; align-items: center; gap: 5px; }
.pp-req { color: #f0b429; font-size: 13px; line-height: 1; }
.pp-input { background: #142814; border: 1px solid var(--border2); border-radius: 3px; color: var(--text); font-family: 'IBM Plex Mono',monospace; font-size: 13px; padding: 10px 13px; outline: none; width: 100%; box-sizing: border-box; transition: border-color .15s, box-shadow .15s; }
.pp-input::placeholder { color: var(--text3); }
.pp-input:focus { border-color: rgba(57,211,83,0.50); box-shadow: 0 0 0 3px rgba(57,211,83,.09); }
.pp-input.err, .pp-phone.err { border-color: rgba(255,64,64,.5); }
.pp-hint { font-size: 10px; color: var(--text3); margin-top: 1px; }
.pp-err  { font-size: 10px; color: #ff4040; display: none; }
.pp-err.show { display: block; }
.pp-phone { display: flex; border: 1px solid var(--border2); border-radius: 3px; overflow: hidden; transition: border-color .15s, box-shadow .15s; }
.pp-phone:focus-within { border-color: rgba(57,211,83,0.50); box-shadow: 0 0 0 3px rgba(57,211,83,.09); }
.pp-pfx { background: #1a3a1a; border-right: 1px solid var(--border2); color: var(--text2); font-family: 'IBM Plex Mono',monospace; font-size: 13px; padding: 10px 12px; display: flex; align-items: center; gap: 5px; flex-shrink: 0; white-space: nowrap; }
.pp-pnum { background: #142814; border: none; color: var(--text); font-family: 'IBM Plex Mono',monospace; font-size: 13px; padding: 10px 13px; outline: none; width: 100%; }
.pp-pnum::placeholder { color: var(--text3); }
.pp-div { height: 1px; margin: 1.375rem 0; background: linear-gradient(90deg, transparent, var(--border2), transparent); }
.pp-contest-box { background: rgba(240,180,41,.04); border: 1px solid rgba(240,180,41,.18); border-radius: 3px; padding: .875rem 1rem; margin-bottom: 1.375rem; font-size: 11px; color: #8a7040; line-height: 1.6; }
.pp-contest-box strong { color: #f0b429; display: block; margin-bottom: .25rem; font-size: 12px; }
.pp-actions { margin-top: 1.5rem; display: flex; flex-direction: column; align-items: center; gap: .5rem; }
.pp-note { font-size: 10px; color: var(--text3); text-align: center; letter-spacing: .04em; }
.pp-submit { width: 100%; display: flex; align-items: center; justify-content: center; gap: 10px; background: rgba(240,180,41,.10); border: 1px solid rgba(240,180,41,0.30); border-radius: 3px; color: #f0b429; font-family: 'IBM Plex Mono',monospace; font-size: 14px; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; padding: 13px 36px; cursor: pointer; transition: all .15s; }
.pp-submit:hover { background: rgba(240,180,41,.18); border-color: rgba(240,180,41,0.55); box-shadow: 0 0 18px rgba(240,180,41,.12); }
.pp-submit:disabled { opacity: .5; cursor: not-allowed; pointer-events: none; }
.pp-spin { width: 14px; height: 14px; border: 2px solid rgba(240,180,41,.3); border-top-color: #f0b429; border-radius: 50%; animation: pp-spin .7s linear infinite; display: none; flex-shrink: 0; }
.pp-submit.loading .pp-spin { display: block; }
.pp-submit.loading .pp-stxt { display: none; }
@keyframes pp-spin { to { transform: rotate(360deg); } }
.pp-ok { display: none; text-align: center; padding: 3rem 1.75rem; }
.pp-ok.show { display: block; }
.pp-ok-ico { width: 62px; height: 62px; margin: 0 auto 1.25rem; border: 2px solid var(--green); border-radius: 50%; display: flex; align-items: center; justify-content: center; box-shadow: 0 0 20px rgba(57,211,83,.22); animation: pp-pop .45s cubic-bezier(.34,1.56,.64,1) forwards; }
@keyframes pp-pop { from{transform:scale(0);opacity:0} to{transform:scale(1);opacity:1} }
.pp-ok-ico svg { color: var(--green); }
.pp-ok-title { font-size: 19px; font-weight: 600; color: var(--green); margin-bottom: .625rem; text-shadow: 0 0 18px rgba(57,211,83,.3); }
.pp-ok-msg   { font-size: 13px; color: var(--text2); line-height: 1.65; margin-bottom: .75rem; }
.pp-ok-meta  { font-size: 11px; color: var(--text3); letter-spacing: .06em; margin-bottom: 1.75rem; }
.pp-back { display: inline-flex; align-items: center; gap: 7px; font-size: 12px; letter-spacing: .1em; text-transform: uppercase; color: var(--text2); border: 1px solid var(--border); padding: 9px 22px; border-radius: 3px; text-decoration: none; transition: all .15s; }
.pp-back:hover { border-color: var(--border2); color: var(--green); }
@media (max-width: 520px) { .pp-row { grid-template-columns: 1fr; } .pp-body,.pp-head { padding: 1.25rem; } }

body.script:
//
  (function(){

  // ── 1. Quiz start time (ISO 8601 with IST offset +05:30) ──
  var QUIZ_START    = new Date('2026-06-14T21:00:00+05:30');

  // ── 2. How long the quiz runs (milliseconds) ──
  var QUIZ_DURATION = 30 * 60 * 1000;

  // ── 3. Button destination URLs — UPDATE THESE ──
  var REGISTER_URL    = '/p/register.html';      // ← your registration page
  var PARTICIPATE_URL = '/p/participate.html';   // ← your quiz/YouTube page

  // ─────────────────────────────────────────────
  //  DO NOT EDIT BELOW THIS LINE
  // ─────────────────────────────────────────────

  var elD          = document.getElementById('cd-d');
  var elH          = document.getElementById('cd-h');
  var elM          = document.getElementById('cd-m');
  var elS          = document.getElementById('cd-s');
  var elCountdown  = document.getElementById('countdown');
  var elStandby    = document.getElementById('badge-standby');
  var elLive       = document.getElementById('badge-live');
  var elEnded      = document.getElementById('badge-ended');
  var btnParticipate = document.getElementById('btn-participate');
  var btnRegister    = document.getElementById('btn-register');

  // Guard: elements only exist on homepage
  if(!elD || !btnRegister || !btnParticipate) return;

  function pad(n){ return String(n).padStart(2,'0'); }

  function tick(){
    var now     = new Date();
    var toStart = QUIZ_START - now;
    var toEnd   = (QUIZ_START.getTime() + QUIZ_DURATION) - now;
    var vals    = [elD, elH, elM, elS];

    if(toStart > 0){
      // Upcoming
      var d  = Math.floor(toStart / 86400000);
      var h  = Math.floor((toStart % 86400000) / 3600000);
      var mn = Math.floor((toStart % 3600000)  / 60000);
      var sc = Math.floor((toStart % 60000)    / 1000);
      elD.textContent = pad(d);
      elH.textContent = pad(h);
      elM.textContent = pad(mn);
      elS.textContent = pad(sc);
      vals.forEach(function(el){
        el.classList.remove('warn','danger');
        if(toStart < 3600000)      el.classList.add('danger');
        else if(toStart < 7200000) el.classList.add('warn');
      });
      elStandby.style.display = '';
      elLive.style.display    = 'none';
      elEnded.style.display   = 'none';
      btnParticipate.className = 'qz-btn btn-participate';

    } else if(toEnd > 0){
      // LIVE
      var rm = Math.floor(toEnd / 60000);
      var rs = Math.floor((toEnd % 60000) / 1000);
      elD.textContent = '00';
      elH.textContent = '00';
      elM.textContent = pad(rm);
      elS.textContent = pad(rs);
      vals.forEach(function(el){ el.className = 'tac-val danger'; });
      elStandby.style.display = 'none';
      elLive.style.display    = '';
      elEnded.style.display   = 'none';
      btnParticipate.className = 'qz-btn btn-participate is-live';

    } else {
      // Ended
      elCountdown.style.display = 'none';
      elStandby.style.display   = 'none';
      elLive.style.display      = 'none';
      elEnded.style.display     = '';
      btnParticipate.className  = 'qz-btn btn-participate';
    }
  }

  // Set button destinations from config (overrides the href in HTML)
  btnRegister.setAttribute('href', REGISTER_URL);
  btnParticipate.setAttribute('href', PARTICIPATE_URL);

  tick();
  setInterval(tick, 1000);

  })();

  // ── Registration page ──
  (function(){
  var isReg = /\/p\/register/i.test(window.location.pathname);
  if(!isReg) return;

  var regWrap = document.getElementById('reg-wrap');
  if(regWrap) regWrap.style.display = 'block';

  // Hide mission card, blog widget and divider on register page
  var mCard = document.querySelector('.mission-card');
  if(mCard) mCard.style.display = 'none';
  var blogWid = document.querySelector('.widget.Blog');
  if(blogWid) blogWid.style.display = 'none';
  var divider = document.querySelector('.qz-divider');
  if(divider) divider.style.display = 'none';

  // Populate DOB dropdowns
  var selD = document.getElementById('rp-dob-d');
  var selM = document.getElementById('rp-dob-m');
  var selY = document.getElementById('rp-dob-y');
  var MON  = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  function rpOpt(sel, val, lbl) {
    var o = document.createElement('option');
    o.value = val; o.textContent = lbl || val; sel.appendChild(o);
  }
  rpOpt(selD,'','DD'); rpOpt(selM,'','MM'); rpOpt(selY,'','YYYY');
  for(var d=1;d<=31;d++) rpOpt(selD,d,d<10?'0'+d:d);
  for(var m=0;m<12;m++) rpOpt(selM,m+1,MON[m]);
  var y0 = new Date().getFullYear();
  for(var y=y0-15;y>=y0-60;y--) rpOpt(selY,y);

  // Subscribe radio toggle
  var optYes = document.getElementById('rp-opt-yes');
  var optNo  = document.getElementById('rp-opt-no');
  var subBox = document.getElementById('rp-sub-prompt');
  var radios = document.querySelectorAll('input[name="rp-sub"]');
  for(var ri=0;ri<radios.length;ri++){
    radios[ri].addEventListener('change', function(){
      optYes.classList.remove('yes','no');
      optNo.classList.remove('yes','no');
      document.getElementById('rp-err-sub').classList.remove('show');
      if(this.value==='Yes'){ optYes.classList.add('yes'); subBox.classList.remove('show'); }
      else { optNo.classList.add('no'); subBox.classList.add('show'); }
    });
  }

  // WhatsApp digits only
  var waEl = document.getElementById('rp-wa');
  if(waEl) waEl.addEventListener('input', function(){ this.value = this.value.replace(/\D/g,'').slice(0,10); });

  // Validation
  function chk(id, eid, pw, fn) {
    var el = document.getElementById(id);
    var err = document.getElementById(eid);
    var ww = pw ? document.getElementById(pw) : null;
    var ok = fn(el.value);
    el.classList.toggle('err',!ok);
    if(ww) ww.classList.toggle('err',!ok);
    err.classList.toggle('show',!ok);
    return ok;
  }
  function validate() {
    var ok = true;
    ok = chk('rp-fname','rp-err-fname',null, function(v){ return v.trim().length>=2; }) && ok;
    ok = chk('rp-lname','rp-err-lname',null, function(v){ return v.trim().length>=2; }) && ok;
    ok = chk('rp-email','rp-err-email',null, function(v){ return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()); }) && ok;
    ok = chk('rp-wa','rp-err-wa','rp-phone', function(v){ return /^\d{10}$/.test(v); }) && ok;
    ok = chk('rp-gender','rp-err-gender',null, function(v){ return v!==''; }) && ok;
    var dobOk = selD.value && selM.value && selY.value;
    document.getElementById('rp-err-dob').classList.toggle('show',!dobOk);
    if(!dobOk) ok = false;
    var sc = document.querySelector('input[name="rp-sub"]:checked');
    document.getElementById('rp-err-sub').classList.toggle('show',!sc);
    if(!sc) ok = false;
    return ok;
  }

  // Submit
  var GF = 'https://docs.google.com/forms/d/e/1FAIpQLSdn3T2JLbJBOwSJVH5JueaObUQbtJZSqocTquTjXWgh72wNQQ/formResponse';
  var E  = { name:'entry.304816631', email:'entry.1557075527', wa:'entry.1218916148', gen:'entry.1885205178', dy:'entry.1199713675_year', dm:'entry.1199713675_month', dd:'entry.1199713675_day', sub:'entry.902891137' };
  var rpFormEl = document.getElementById('rp-form');
  if(rpFormEl) rpFormEl.addEventListener('submit', function(e){
    e.preventDefault();
    if(!validate()) return;
    var fn = document.getElementById('rp-fname').value.trim();
    var ln = document.getElementById('rp-lname').value.trim();
    var em = document.getElementById('rp-email').value.trim();
    var wa = document.getElementById('rp-wa').value.trim();
    var gn = document.getElementById('rp-gender').value;
    var sv = document.querySelector('input[name="rp-sub"]:checked').value;
    var fd = new URLSearchParams();
    fd.append(E.name,fn+' '+ln); fd.append(E.email,em); fd.append(E.wa,'+91'+wa);
    fd.append(E.gen,gn); fd.append(E.dy,selY.value); fd.append(E.dm,selM.value);
    fd.append(E.dd,selD.value); fd.append(E.sub,sv);
    fd.append('fvv','1'); fd.append('pageHistory','0');
    var btn = document.getElementById('rp-btn');
    btn.classList.add('loading'); btn.disabled = true;
    fetch(GF,{method:'POST',mode:'no-cors',body:fd})
      .catch(function(){})
      .finally(function(){
        document.getElementById('rp-form-body').style.display='none';
        document.getElementById('rp-ok').classList.add('show');
        document.getElementById('rp-ok-meta').textContent=fn+' '+ln+' · '+em;
      });
  });

  // Clear errors on input
  var clearIds = ['rp-fname','rp-lname','rp-email','rp-gender'];
  for(var ci=0;ci<clearIds.length;ci++){
    (function(id){
      var el = document.getElementById(id);
      if(!el) return;
      el.addEventListener('input', function(){
        this.classList.remove('err');
        var e = document.getElementById('rp-err-'+id.replace('rp-',''));
        if(e) e.classList.remove('show');
      });
    })(clearIds[ci]);
  }
  })();

  // ── Participate page ──
  (function(){
  var isPP = /\/p\/participate/i.test(window.location.pathname);
  if(!isPP) return;

  var ppWrap = document.getElementById('pp-wrap');
  if(ppWrap) ppWrap.style.display = 'block';

  var mCard = document.querySelector('.mission-card');
  if(mCard) mCard.style.display = 'none';
  var blogWid = document.querySelector('.widget.Blog');
  if(blogWid) blogWid.style.display = 'none';
  var divider = document.querySelector('.qz-divider');
  if(divider) divider.style.display = 'none';

  var ppWaEl = document.getElementById('pp-wa');
  if(ppWaEl) ppWaEl.addEventListener('input', function(){ this.value = this.value.replace(/\D/g,'').slice(0,10); });

  function ppChk(id, eid, pw, fn) {
    var el = document.getElementById(id);
    var err = document.getElementById(eid);
    var ww = pw ? document.getElementById(pw) : null;
    var ok = fn(el.value);
    el.classList.toggle('err',!ok);
    if(ww) ww.classList.toggle('err',!ok);
    err.classList.toggle('show',!ok);
    return ok;
  }
  function ppValidate() {
    var ok = true;
    ok = ppChk('pp-fname','pp-err-fname',null,     function(v){ return v.trim().length>=2; }) && ok;
    ok = ppChk('pp-lname','pp-err-lname',null,     function(v){ return v.trim().length>=2; }) && ok;
    ok = ppChk('pp-wa','pp-err-wa','pp-phone',     function(v){ return /^\d{10}$/.test(v); }) && ok;
    ok = ppChk('pp-channel','pp-err-channel',null, function(v){ return v.trim().length>=2; }) && ok;
    ok = ppChk('pp-contest','pp-err-contest',null, function(v){ return v.trim().length>=2; }) && ok;
    return ok;
  }

  var PP_GF = 'https://docs.google.com/forms/d/e/1FAIpQLSdTLbM8li5tk7TIjx0rj5Ce2nl5-tIT2z2wpvNrNCr-Xnv6Mw/formResponse';
  var PP_E  = { name:'entry.1930094438', wa:'entry.774527992', channel:'entry.1544801000', contest:'entry.669208939' };

  var ppFormEl = document.getElementById('pp-form');
  if(ppFormEl) ppFormEl.addEventListener('submit', function(e){
    e.preventDefault();
    if(!ppValidate()) return;
    var fn = document.getElementById('pp-fname').value.trim();
    var ln = document.getElementById('pp-lname').value.trim();
    var wa = document.getElementById('pp-wa').value.trim();
    var ch = document.getElementById('pp-channel').value.trim();
    var ct = document.getElementById('pp-contest').value.trim();
    var fd = new URLSearchParams();
    fd.append(PP_E.name, fn+' '+ln);
    fd.append(PP_E.wa, '+91'+wa);
    fd.append(PP_E.channel, ch);
    fd.append(PP_E.contest, ct);
    fd.append('fvv','1');
    fd.append('pageHistory','0');
    var btn = document.getElementById('pp-btn');
    btn.classList.add('loading'); btn.disabled = true;
    fetch(PP_GF,{method:'POST',mode:'no-cors',body:fd})
      .catch(function(){})
      .finally(function(){
        document.getElementById('pp-form-body').style.display='none';
        document.getElementById('pp-ok').classList.add('show');
        document.getElementById('pp-ok-meta').textContent=fn+' '+ln+' · '+ch;
      });
  });

  var ppClearIds = ['pp-fname','pp-lname','pp-channel','pp-contest'];
  for(var pci=0;pci<ppClearIds.length;pci++){
    (function(id){
      var el = document.getElementById(id);
      if(!el) return;
      el.addEventListener('input', function(){
        this.classList.remove('err');
        var e = document.getElementById('pp-err-'+id.replace('pp-',''));
        if(e) e.classList.remove('show');
      });
    })(ppClearIds[pci]);
  }
  })();
  //
